     {layer==='generation'&&generationSource!=='regional'&&generationSource!=='enexis'&&<details className="map-options"><summary>Dataset &amp; overlays</summary><div className="catalogue-controls"><label>Producer dataset<select aria-label="Producer dataset" value={generationSource} onChange={e=>{setGenerationSource(e.target.value);setQuery('');setSelected(e.target.value==='mapped'?'producer:overview':assets[0].id);}}><option value="mapped">Mapped wind &amp; solar</option><option value="historical">Historical registry (71)</option></select></label>{stationError&&<p role="alert">{stationError}</p>}</div></details>}
